begin;
set local role postgres;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select plan(141);
select has_table('public','payment_history_runtime','dedicated runtime');
select has_table('public','payment_history_movement_versions','dedicated versioned ledger');
select has_table('public','payment_history_receipts','immutable receipts');
select ok((select bool_and(relrowsecurity) from pg_class where relnamespace='public'::regnamespace and relkind='r' and relname like 'payment_history_%'),'RLS enabled on every ledger table');
select ok(not has_table_privilege('service_role','public.payment_history_jobs','SELECT'),'service role has no direct job table surface');
select ok(not has_table_privilege('authenticated','public.payment_history_jobs','SELECT'),'browser cannot see worker leases');
select ok(not has_table_privilege('authenticated','public.payment_history_movement_versions','INSERT'),'browser cannot create money');
select ok(not has_function_privilege('anon','public.payment_history_request_v1(uuid,text,jsonb,uuid,uuid,text,integer)','EXECUTE'),'anonymous denied');
select ok(not has_function_privilege('authenticated','public.payment_history_worker_v1(text,jsonb)','EXECUTE'),'browser cannot stage rows');
select is(app_private.payment_history_ticks_v1('0001-01-01T00:00:00.0000001'),'1'::bigint,'100ns preserved independently of PG timestamp precision');
select is(app_private.payment_history_ticks_v1('2024-01-31T16:12:13.4567000'),'638423143334567000'::bigint,'ticks equal independent CLR');
select is(app_private.payment_history_field_hash_v1(array['getnet-merchant-alias-v1','Synthetic Merchant','','','','']),'07aad10f6d3df03e3870a76b0e6dc0f22f37e703c89162113e8ac6fc21c70ab3','alias hash equals independent qualified CLR');

-- ASCII length optimization: independent frozen Node protocol expected values,
-- source f0769da781f0b7f53b42aa343513353e986eabd2, verified against five existing
-- CLR literals from client 5d1052030cf4e72ce96b524c6d4e32d940ca7b2b.
-- Corpus SHA256 dbf5df58e0f2f01515a2cbd43880af78307ff6f2fde0e542e4aff4bcd1175936.
-- No fresh CLR execution: local policy denied it. NUL remains CLR/Node-only;
-- PostgreSQL text cannot represent it. SQL NULL array uses the zero-field fold.
-- Payload cases test digest/framing, not domain admission or real transactions.
create function pg_temp.asus019_field_hash_preimage(p_fields text[]) returns text
language sql immutable set search_path='' as $$
 select encode(extensions.digest(convert_to(coalesce(string_agg(
   coalesce((select sum(case when ascii(substr(coalesce(f,''),n,1))>65535 then 2 else 1 end)
      from generate_series(1,length(coalesce(f,''))) n),0)::text||':'||coalesce(f,''),'' order by ord),''),'UTF8'),'sha256'),'hex')
 from unnest(p_fields) with ordinality x(f,ord);
$$;
create function pg_temp.asus019_entity_digest_preimage(p_kind text,p jsonb) returns text
language plpgsql immutable set search_path='' as $$
declare fields text[];k text;v_fields text[]:=array['history-replica-entity-v1',p_kind];begin
 if p_kind='batch' then fields:=array['id','origin','state','apply_operation_id','created_revision','cancelled_revision','created_utc_ms'];
 elsif p_kind='movement' then fields:=array['id','merchant_id','batch_id','identity_key','economic_digest','active','business_ticks','gross_clp','fee_clp','fee_vat_clp','net_clp','movement_kind','transaction_state','external_namespace','external_id','source_sheet','source_row','timestamp_raw','offset_minutes','occurred_at_utc','time_interpretation','time_policy_version','time_evidence_reference','card_subtype','created_revision'];
 else raise exception using errcode='22023',message='payment_history_replica_kind_invalid';end if;
 foreach k in array fields loop v_fields:=array_append(v_fields,coalesce(p->>k,'null'));end loop;
 return pg_temp.asus019_field_hash_preimage(v_fields);
end;$$;

select is(current_setting('server_encoding'),'UTF8','field hash fast path is qualified only for server UTF8');
select is((select encode(extensions.digest(convert_to(prosrc,'UTF8'),'sha256'),'hex') from pg_proc
 where oid='app_private.payment_history_field_hash_v1(text[])'::regprocedure),
 'e7d56862979190a43884c2607cf774a28935d4dbdd4e104e0e5a62b99a538f42','only reviewed ASCII field hash body is installed');
select is((select encode(extensions.digest(convert_to(prosrc,'UTF8'),'sha256'),'hex') from pg_proc
 where oid='pg_temp.asus019_field_hash_preimage(text[])'::regprocedure),
 '69cd72ed4474105a1c70a8000f7e39aecf7d15cdbdc5e10ad2f4a194aa1bda87','SQL oracle is the exact original preimage');
select ok((select p.proowner='postgres'::regrole and l.lanname='sql' and p.prokind='f' and p.provolatile='i'
 and p.proparallel='u' and not p.prosecdef and not p.proisstrict and not p.proleakproof
 and p.prorettype='text'::regtype and p.pronargs=1 and p.proargtypes[0]='text[]'::regtype
 and p.proargnames=array['p_fields']::text[] and p.pronargdefaults=0
 and p.proconfig=array['search_path=""']::text[] and p.procost=100 and p.prorows=0
 from pg_proc p join pg_language l on l.oid=p.prolang
 where p.oid='app_private.payment_history_field_hash_v1(text[])'::regprocedure),
 'field hash owner signature language volatility null handling and search path are preserved');
select ok(not has_function_privilege('anon','app_private.payment_history_field_hash_v1(text[])','EXECUTE')
 and not has_function_privilege('authenticated','app_private.payment_history_field_hash_v1(text[])','EXECUTE')
 and not has_function_privilege('service_role','app_private.payment_history_field_hash_v1(text[])','EXECUTE')
 and not exists(select 1 from pg_proc p cross join lateral aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a
  where p.oid='app_private.payment_history_field_hash_v1(text[])'::regprocedure and a.grantee<>p.proowner),
 'private field hash has no non-owner execution grant');
create temp table asus019_hash_vectors as
 select v->>'name' as name,case when jsonb_typeof(v->'fields')='null' then null::text[]
  else array(select x.value from jsonb_array_elements_text(v->'fields') with ordinality x(value,ord) order by x.ord) end as fields,
 v->>'expectedSha256' as expected
 from jsonb_array_elements($field_corpus$[{"name":"sql_null_array","fields":null,"expectedSha256":"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855"},{"name":"empty_array","fields":[],"expectedSha256":"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855"},{"name":"single_null","fields":[null],"expectedSha256":"ba768b331fd86cec803be04e56ab2b3d4c0e98ef4ee4fcd4e72ad7cce61a1d1f"},{"name":"single_empty","fields":[""],"expectedSha256":"ba768b331fd86cec803be04e56ab2b3d4c0e98ef4ee4fcd4e72ad7cce61a1d1f"},{"name":"null_empty_interleaved","fields":[null,"",null,""],"expectedSha256":"8538098a725acce2a400276987f134753b5125003e70c7d36420d4e1e50a036c"},{"name":"existing_ascii_golden","fields":[null,"","abc","00123","x:y"],"expectedSha256":"ef190b0a9da337a1b484e512e0bfb750e03a6dd36a62695dd86fb11162b31554"},{"name":"ascii_trailing_spaces","fields":[" leading","trailing "," both ","   "],"expectedSha256":"e432731fed85f178d7fd8f054686eac6e8b95c7f019ae9b3efbc4dc177bf22bc"},{"name":"ascii_framing_colons","fields":["0:","1:a",":","00123","10"],"expectedSha256":"b02b43a6f16c6b2051a4a147352aa4f63066ad3525be1746b440a906b8942dc2"},{"name":"ascii_tab_newline","fields":["a\tb","line1\nline2","\r\n","\t"],"expectedSha256":"133054f89a937f35425609a96275b5b0df4441053ce69123946bfb282485a562"},{"name":"ascii_control_bounds","fields":["\u0001","\u007f","A\u0001B\u007fC"],"expectedSha256":"50b899fea0d6e7af5d0f07c8758db3f7f8ad658e3abeb524e6767db5c0e0213e"},{"name":"order_ab","fields":["ab","c"],"expectedSha256":"430fb1b4ac43316eca81fab27a1930ab8eff8fef6a1dc7903dce44bbc2790dc5"},{"name":"order_ba","fields":["c","ab"],"expectedSha256":"35f6135a85492b28d3891327685cdb55f24f2b4c4d677aa334b643d97495a45f"},{"name":"field_boundary_a_bc","fields":["a","bc"],"expectedSha256":"5310a58788781ab25d5ad7c3f85035824b4eb7bdfa394e0ac2186271472b5492"},{"name":"literal_null","fields":["null"],"expectedSha256":"b8af3a27baee0bec78df6dd028f5e140b3357846c8332e50ff20e736a71cac83"},{"name":"bmp_non_a