e":"nullable_economics","fields":["historical-economics-v1","638423827330000000","1200","null","null","null","Sale","ABONADO"],"expectedSha256":"841001d29d86768c0a7fdee83a1cfc4957bcfaf62aa3ad965b928d8cbc1a141d"}]$field_corpus$::jsonb) v;
